update.if:
UPDATE ins_car_series_info t
t.del_flag = 1
WHERE t.id = #{id}

mapper.select:
SELECT

FROM
ins_car_series_info t
where 1

    and t.name = #{name}


    and t.name_en = #{nameEn}


    and t.brand_id = #{brandId}


    and t.alias = #{alias}


    and t.exclusion_words = #{exclusionWords}


    and t.code = #{code}


    and t.order_by = #{orderBy}


    and t.car_level1 = #{carLevel1}


    and t.car_level2 = #{carLevel2}


    and t.energy_type1 = #{energyType1}


    and t.energy_type2 = #{energyType2}


    and t.operator = #{operator}


    and t.create_time = #{createTime}


    and t.update_time = #{updateTime}


    and t.del_flag = #{delFlag}


    and t.img = #{img}


    and t.app_id = #{appId}

order by update_time desc
limit #{start},#{pagesize}

SELECT

FROM
ins_car_series_info t
where 1 = 1

    and t.name = #{name}


    and t.name_en = #{nameEn}


    and t.brand_id = #{brandId}


    and t.brand_code = #{brandCode}


    and t.alias = #{alias}


    and t.exclusion_words = #{exclusionWords}


    and t.code = #{code}


    and t.status = #{status}


    and t.order_by = #{orderBy}


    and t.operator = #{operator}


    and t.competitive_type = #{competitiveType}


    and t.brand_code in

        #{item}


order by case when name like '%非指代%' then 0 else 1 end,code asc

select icsi.id, icsi.name, icsi.competitive_type, -- sdi.item_text as competitiveTypeName, icsi.update_user as operator, icsi.is_core, -- sd.item_text as isCoreName, icsi.create_time, icsi.update_time, icsi.status, -- sd1.item_text as statusName, ibi.name as brandName, icsi.is_new_car, icsi.preheat_start_time, icsi.preheat_end_time, icsi.launch_start_time, icsi.launch_end_time, icsi.stable_start_time, icsi.stable_end_time from ins_car_series_info icsi left join ins_brand_info ibi on ibi.code = icsi.brand_code where 1=1
and icsi.name like concat('%',#{carSeriesModel.name},'%')
and icsi.brand_code = #{carSeriesModel.brandCode}
and icsi.status = #{carSeriesModel.status}
and icsi.is_core = #{carSeriesModel.isCore}
and icsi.competitive_type = #{carSeriesModel.competitiveType}
and icsi.update_user like concat('%',#{carSeriesModel.operator},'%')
and icsi.brand_code in
#{item}
and icsi.is_new_car = #{carSeriesModel.isNewCar}
order by icsi.${carSeriesModel.order}
order by icsi.competitive_type asc,icsi.is_core desc,icsi.code asc
